-- =====================================================================
-- JanuMart - H2 compatible seed data
-- Sections: users, products, cart_items, orders, order_items, reviews
-- Deterministic identity note: rows are inserted in file order, so the
-- first 9 users (admin, then 8 sellers) get ids 1..9 and buyers get 10..11.
-- =====================================================================

----
-- USERS (1 admin, 8 sellers, 2 buyers) => ids 1..11
----

----
-- PRODUCTS (122) => ids 1..122 in insert order
-- Sellers: StyleHub=2, Trendy Touch=3, Urban Accessories=4, Fashion Nest=5,
--          Daily Essentials=6, Elegant Choice=7, TravelMate Store=8, Gift Corner=9
----

----
-- CART_ITEMS (buyer demo@janumart.com = user 10)
----

----
-- ORDERS (ids 1..8 in insert order)
-- 1..6 = demo@janumart.com (2 DELIVERED, 1 SHIPPED, 2 CONFIRMED, 1 CANCELLED)
-- 7..8 = ritika.sharma@example.com (1 DELIVERED, 1 CONFIRMED)
----

----
-- ORDER_ITEMS (43 rows; unit prices match the seeded product prices)
----

----
-- REVIEWS (30) - only for products inside DELIVERED orders, dated after them
----

----
-- Safe identity restarts so future auto-increments never collide
----
ALTER TABLE users ALTER COLUMN id RESTART WITH 100;
ALTER TABLE products ALTER COLUMN id RESTART WITH 300;
ALTER TABLE cart_items ALTER COLUMN id RESTART WITH 100;
ALTER TABLE orders ALTER COLUMN id RESTART WITH 100;
ALTER TABLE order_items ALTER COLUMN id RESTART WITH 300;
ALTER TABLE reviews ALTER COLUMN id RESTART WITH 200;
